DROP TABLE IF EXISTS `attendance`;
CREATE TABLE `attendance` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL,
  `att_date` date NOT NULL,
  `status` enum('present','absent','half_day','leave','holiday','week_off') COLLATE utf8mb4_unicode_ci NOT NULL,
  `leave_request_id` bigint unsigned DEFAULT NULL,
  `check_in_at` datetime DEFAULT NULL,
  `check_out_at` datetime DEFAULT NULL,
  `overtime_minutes` smallint unsigned NOT NULL DEFAULT '0',
  `source` enum('manual','self','system') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `remarks` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `corrected` tinyint(1) NOT NULL DEFAULT '0',
  `correction_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_att` (`employee_id`,`att_date`),
  KEY `idx_att_date` (`att_date`),
  KEY `fk_att_lr` (`leave_request_id`),
  CONSTRAINT `fk_att_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_att_lr` FOREIGN KEY (`leave_request_id`) REFERENCES `leave_requests` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `occurred_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `user_id` int unsigned DEFAULT NULL,
  `actor_type` enum('user','system','cron','ai_service') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'user',
  `action` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_type` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `entity_id` bigint unsigned DEFAULT NULL,
  `summary` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `before_data` json DEFAULT NULL,
  `after_data` json DEFAULT NULL,
  `meta` json DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prev_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `row_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'sha256 chain for tamper evidence',
  PRIMARY KEY (`id`),
  KEY `idx_al_entity` (`entity_type`,`entity_id`),
  KEY `idx_al_user` (`user_id`,`occurred_at`),
  KEY `idx_al_action` (`action`,`occurred_at`),
  KEY `idx_al_occurred` (`occurred_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

