  UNIQUE KEY `uq_bil_hash` (`bank_cash_account_id`,`line_hash`),
  KEY `idx_bil_status` (`bank_cash_account_id`,`match_status`,`txn_date`),
  KEY `fk_bil_import` (`bank_import_id`),
  CONSTRAINT `fk_bil_bca` FOREIGN KEY (`bank_cash_account_id`) REFERENCES `bank_cash_accounts` (`id`),
  CONSTRAINT `fk_bil_import` FOREIGN KEY (`bank_import_id`) REFERENCES `bank_imports` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `bank_imports`;
CREATE TABLE `bank_imports` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `bank_cash_account_id` int unsigned NOT NULL,
  `stored_file_id` bigint unsigned DEFAULT NULL,
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `statement_from` date DEFAULT NULL,
  `statement_to` date DEFAULT NULL,
  `rows_total` int unsigned NOT NULL DEFAULT '0',
  `rows_imported` int unsigned NOT NULL DEFAULT '0',
  `rows_duplicate` int unsigned NOT NULL DEFAULT '0',
  `rows_error` int unsigned NOT NULL DEFAULT '0',
  `imported_by` int unsigned DEFAULT NULL,
  `imported_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_bi_bca` (`bank_cash_account_id`),
  KEY `fk_bi_file` (`stored_file_id`),
  CONSTRAINT `fk_bi_bca` FOREIGN KEY (`bank_cash_account_id`) REFERENCES `bank_cash_accounts` (`id`),
  CONSTRAINT `fk_bi_file` FOREIGN KEY (`stored_file_id`) REFERENCES `stored_files` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `billing_document_snapshots`;
CREATE TABLE `billing_document_snapshots` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_id` bigint unsigned NOT NULL,
  `supplier` json NOT NULL COMMENT 'legal identity as at issuance',
  `customer` json NOT NULL,
  `bank` json DEFAULT NULL COMMENT 'only fields actually printed — never CIF',
  `branding` json DEFAULT NULL COMMENT 'asset ids, versions, sha256',
  `template` json NOT NULL,
  `line_items` json NOT NULL,
  `tax_summary` json NOT NULL,
  `totals` json NOT NULL,
  `content_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bds_doc` (`document_id`),
  CONSTRAINT `fk_bds_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `billing_documents`;
CREATE TABLE `billing_documents` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `doc_type` enum('tax_invoice','bill_of_supply','cash_memo','estimate','quotation','proforma','credit_note','debit_note') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('draft','finalized','cancelled','converted','expired') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `draft_ref` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'internal id before finalization; never printed as statutory number',
  `sequence_id` int unsigned DEFAULT NULL,
  `sequence_number` int unsigned DEFAULT NULL,
  `document_number` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'assigned only at finalization',
  `financial_year_id` int unsigned DEFAULT NULL,
  `contact_id` bigint unsigned NOT NULL,
  `issue_date` date NOT NULL,
  `supply_date` date DEFAULT NULL,
  `service_period_from` date DEFAULT NULL,
  `service_period_to` date DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `reference_no` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `po_number` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bill_to_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bill_to_gstin` char(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bill_to_address` text COLLATE utf8mb4_unicode_ci,
  `bill_to_state_code` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bill_to_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bill_to_email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_type` enum('b2b','b2c','export','sez') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'b2c',
  `supplier_gstin` char(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supplier_state_code` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `place_of_supply_state_code` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_sez_recipient` tinyint(1) NOT NULL DEFAULT '0',
  `export_type` enum('none','with_payment','lut') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `gst_type` enum('cgst_sgst','cgst_utgst','igst','none') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reverse_charge` tinyint(1) NOT NULL DEFAULT '0',
  `tax_review_status` enum('auto_ok','needs_review','resolved','blocked') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'needs_review',
  `tax_review_reason` text COLLATE utf8mb4_unicode_ci,
  `tax_reviewed_by` int unsigned DEFAULT NULL,
  `tax_reviewed_at` datetime DEFAULT NULL,
  `tax_advice` json DEFAULT NULL COMMENT 'suggestion + warnings at last calculation',
  `price_mode` enum('exclusive','inclusive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'exclusive',
  `subtotal` decimal(15,2) NOT NULL DEFAULT '0.00',
  `discount_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `taxable_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `cgst_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `sgst_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `utgst_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `igst_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `cess_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `tax_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `round_off` decimal(15,2) NOT NULL DEFAULT '0.00',
  `grand_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `amount_paid` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'derived from payment_allocations',
  `amount_credited` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'derived from finalized credit notes',
  `balance_due` decimal(15,2) NOT NULL DEFAULT '0.00',
  `payment_status` enum('na','unpaid','partial','paid','overpaid') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'na',
  `amount_in_words` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `terms` text COLLATE utf8mb4_unicode_ci,
  `internal_notes` text COLLATE utf8mb4_unicode_ci,
  `bank_account_id` int unsigned DEFAULT NULL,
  `template_id` int unsigned DEFAULT NULL,
  `template_version` int unsigned DEFAULT NULL,
  `apply_signature` tinyint(1) NOT NULL DEFAULT '0',
  `signed_by` int unsigned DEFAULT NULL,
  `signed_at` datetime DEFAULT NULL,
  `original_document_id` bigint unsigned DEFAULT NULL COMMENT 'credit/debit note → original invoice',
  `converted_from_id` bigint unsigned DEFAULT NULL COMMENT 'estimate → invoice',
  `duplicated_from_id` bigint unsigned DEFAULT NULL,
  `recurring_profile_id` int unsigned DEFAULT NULL,
  `lead_id` bigint unsigned DEFAULT NULL,
  `journal_entry_id` bigint unsigned DEFAULT NULL,
  `einvoice_irn` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'only when a real IRP integration exists',
  `einvoice_ack_no` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `einvoice_ack_date` datetime DEFAULT NULL,
  `cancel_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cancelled_by` int unsigned DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `lock_version` int unsigned NOT NULL DEFAULT '1' COMMENT 'optimistic lock for drafts/autosave',
  `finalized_by` int unsigned DEFAULT NULL,
  `finalized_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bd_draft_ref` (`draft_ref`),
  UNIQUE KEY `uq_bd_number` (`financial_year_id`,`document_number`),
  UNIQUE KEY `uq_bd_seq` (`sequence_id`,`sequence_number`),
  KEY `idx_bd_type` (`doc_type`,`status`,`issue_date`),
  KEY `idx_bd_contact` (`contact_id`,`status`),
  KEY `idx_bd_creator` (`created_by`),
  KEY `idx_bd_original` (`original_document_id`),
  KEY `fk_bd_pos` (`place_of_supply_state_code`),
  KEY `fk_bd_bank` (`bank_account_id`),
  KEY `fk_bd_tpl` (`template_id`),
  KEY `fk_bd_conv` (`converted_from_id`),
  KEY `fk_bd_je` (`journal_entry_id`),
  KEY `fk_bd_lead` (`lead_id`),
  CONSTRAINT `fk_bd_bank` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_cash_accounts` (`id`),
  CONSTRAINT `fk_bd_contact` FOREIGN KEY (`contact_id`) REFERENCES `contacts` (`id`),
  CONSTRAINT `fk_bd_conv` FOREIGN KEY (`converted_from_id`) REFERENCES `billing_documents` (`id`),
  CONSTRAINT `fk_bd_fy` FOREIGN KEY (`financial_year_id`) REFERENCES `financial_years` (`id`),
  CONSTRAINT `fk_bd_je` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`),
  CONSTRAINT `fk_bd_lead` FOREIGN KEY (`lead_id`) REFERENCES `leads` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_bd_orig` FOREIGN KEY (`original_document_id`) REFERENCES `billing_documents` (`id`),
  CONSTRAINT `fk_bd_pos` FOREIGN KEY (`place_of_supply_state_code`) REFERENCES `states` (`code`),
  CONSTRAINT `fk_bd_seq` FOREIGN KEY (`sequence_id`) REFERENCES `document_sequences` (`id`),
  CONSTRAINT `fk_bd_tpl` FOREIGN KEY (`template_id`) REFERENCES `document_templates` (`id`),
  CONSTRAINT `chk_bd_final_number` CHECK (((`status` <> _utf8mb4'finalized') or (`document_number` is not null) or (`doc_type` in (_utf8mb4'estimate',_utf8mb4'quotation',_utf8mb4'proforma'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `billing_line_items`;
CREATE TABLE `billing_line_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_id` bigint unsigned NOT NULL,
  `line_no` smallint unsigned NOT NULL,
  `service_id` int unsigned DEFAULT NULL,
  `item_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `sac_code` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qty` decimal(14,3) NOT NULL DEFAULT '1.000',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit_rate` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `discount_type` enum('amount','percent') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'amount',
  `discount_value` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `gross_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `discount_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `taxable_value` decimal(15,2) NOT NULL DEFAULT '0.00',
  `tax_treatment` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'regular',
  `gst_rate` decimal(6,3) NOT NULL DEFAULT '0.000',
  `cgst_rate` decimal(6,3) NOT NULL DEFAULT '0.000',
  `cgst_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `sgst_rate` decimal(6,3) NOT NULL DEFAULT '0.000',
  `sgst_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `utgst_rate` decimal(6,3) NOT NULL DEFAULT '0.000',
  `utgst_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `igst_rate` decimal(6,3) NOT NULL DEFAULT '0.000',
  `igst_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `cess_rate` decimal(6,3) NOT NULL DEFAULT '0.000',
  `cess_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `line_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bli` (`document_id`,`line_no`),
  KEY `fk_bli_svc` (`service_id`),
  KEY `fk_bli_treat` (`tax_treatment`),
  CONSTRAINT `fk_bli_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`),
  CONSTRAINT `fk_bli_svc` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_bli_treat` FOREIGN KEY (`tax_treatment`) REFERENCES `tax_treatments` (`code`),
  CONSTRAINT `chk_bli_split` CHECK (((`igst_amount` <= 0) or ((`cgst_amount` <= 0) and (`sgst_amount` <= 0) and (`utgst_amount` <= 0)))),
  CONSTRAINT `chk_bli_state` CHECK (((`sgst_amount` <= 0) or (`utgst_amount` <= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `billing_share_links`;
CREATE TABLE `billing_share_links` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_id` bigint unsigned NOT NULL,
  `token_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime NOT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `access_count` int unsigned NOT NULL DEFAULT '0',
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bsl` (`token_hash`),
  KEY `fk_bsl_doc` (`document_id`),
  CONSTRAINT `fk_bsl_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `billing_taxes`;
CREATE TABLE `billing_taxes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_id` bigint unsigned NOT NULL,
  `tax_type` enum('CGST','SGST','UTGST','IGST','CESS') COLLATE utf8mb4_unicode_ci NOT NULL,
  `rate` decimal(6,3) NOT NULL,
  `taxable_value` decimal(15,2) NOT NULL,
  `tax_amount` decimal(15,2) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bt` (`document_id`,`tax_type`,`rate`),
  CONSTRAINT `fk_bt_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `branding_assets`;
CREATE TABLE `branding_assets` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `asset_type` enum('logo','signature','stamp','sign_stamp','upi_qr','letterhead') COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` int unsigned NOT NULL,
  `stored_file_id` bigint unsigned NOT NULL,
  `width_px` int unsigned DEFAULT NULL,
  `height_px` int unsigned DEFAULT NULL,
  `position_preset` enum('top_left','top_center','top_right','bottom_left','bottom_center','bottom_right') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'top_left',
  `display_width_mm` decimal(5,1) NOT NULL DEFAULT '40.0',
  `enabled_doc_types` json DEFAULT NULL COMMENT 'doc types this asset may appear on',
  `bank_account_id` int unsigned DEFAULT NULL COMMENT 'for UPI QR',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `replaced_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ba` (`asset_type`,`version`),
  KEY `fk_ba_file` (`stored_file_id`),
  KEY `fk_ba_bank` (`bank_account_id`),
  CONSTRAINT `fk_ba_bank` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_cash_accounts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ba_file` FOREIGN KEY (`stored_file_id`) REFERENCES `stored_files` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `call_logs`;
CREATE TABLE `call_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lead_id` bigint unsigned NOT NULL,
  `called_at` datetime NOT NULL,
  `direction` enum('outbound','inbound') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'outbound',
  `person_spoken` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `duration_seconds` int unsigned DEFAULT NULL,
  `outcome` enum('connected','interested','not_interested','call_back','no_answer','busy','switched_off','wrong_number','dnd_requested') COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_connected` tinyint(1) NOT NULL DEFAULT '0',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `next_action` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `next_action_at` datetime DEFAULT NULL,
  `followup_owner_id` int unsigned DEFAULT NULL,
  `caller_id` int unsigned NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_cl_lead` (`lead_id`,`called_at`),
  KEY `idx_cl_caller` (`caller_id`,`called_at`),
  KEY `idx_cl_called` (`called_at`),
  CONSTRAINT `fk_cl_caller` FOREIGN KEY (`caller_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_cl_lead` FOREIGN KEY (`lead_id`) REFERENCES `leads` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `candidate_documents`;
CREATE TABLE `candidate_documents` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `candidate_id` bigint unsigned NOT NULL,
  `doc_kind` enum('cv','assignment','gd_notes','offer_letter','other') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cv',
  `version_no` smallint unsigned NOT NULL DEFAULT '1',
  `stored_file_id` bigint unsigned NOT NULL,
  `parse_status` enum('pending','parsed','failed','unsupported','not_applicable') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `parse_error` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `extracted_text` mediumtext COLLATE utf8mb4_unicode_ci,
  `text_sha256` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_current` tinyint(1) NOT NULL DEFAULT '1',
  `uploaded_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cdoc` (`candidate_id`,`doc_kind`,`version_no`),
  KEY `fk_cdoc_file` (`stored_file_id`),
  CONSTRAINT `fk_cdoc_cand` FOREIGN KEY (`candidate_id`) REFERENCES `candidates` (`id`),
  CONSTRAINT `fk_cdoc_file` FOREIGN KEY (`stored_file_id`) REFERENCES `stored_files` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `candidates`;
CREATE TABLE `candidates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `candidate_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `full_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone_normalized` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `job_opening_id` int unsigned NOT NULL,
  `applied_jd_version_id` int unsigned DEFAULT NULL,
  `application_date` date NOT NULL,
  `source` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('applied','resume_screened','hr_screening','interview_scheduled','interview_completed','assignment_gd','shortlisted','on_hold','rejected','offer_sent','offer_accepted','joined','withdrawn') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'applied',
  `expected_salary` decimal(12,2) DEFAULT NULL COMMENT 'requires hr.salary.view',
  `available_from` date DEFAULT NULL,
  `notice_period_days` smallint unsigned DEFAULT NULL,
  `total_experience_years` decimal(4,1) DEFAULT NULL,
  `linkedin_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `portfolio_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `extracted_skills` json DEFAULT NULL,
  `extracted_education` json DEFAULT NULL,
  `extracted_experience` json DEFAULT NULL,
  `extracted_projects` json DEFAULT NULL,
  `recruiter_notes` text COLLATE utf8mb4_unicode_ci,
  `recruiter_id` int unsigned DEFAULT NULL,
  `consent_given` tinyint(1) NOT NULL DEFAULT '0',
  `consent_at` datetime DEFAULT NULL,
  `consent_text_version` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ai_share_consent` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'consent to send CV text to configured AI provider',
  `retention_until` date DEFAULT NULL,
  `hr_score` decimal(3,1) DEFAULT NULL,
  `employee_id` bigint unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cand_code` (`candidate_code`),
  KEY `idx_cand_job` (`job_opening_id`,`status`),
  KEY `idx_cand_phone` (`phone_normalized`),
  KEY `idx_cand_recruiter` (`recruiter_id`),
  KEY `fk_cand_jdv` (`applied_jd_version_id`),
  KEY `fk_cand_emp` (`employee_id`),
  CONSTRAINT `fk_cand_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cand_jdv` FOREIGN KEY (`applied_jd_version_id`) REFERENCES `job_description_versions` (`id`),
  CONSTRAINT `fk_cand_job` FOREIGN KEY (`job_opening_id`) REFERENCES `job_openings` (`id`),
  CONSTRAINT `fk_cand_rec` FOREIGN KEY (`recruiter_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_cand_score` CHECK (((`hr_score` is null) or ((`hr_score` >= 0) and (`hr_score` <= 10))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `company_profile_versions`;
CREATE TABLE `company_profile_versions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `profile_version` int unsigned NOT NULL,
  `data` json NOT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cpv` (`profile_version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `company_settings`;
CREATE TABLE `company_settings` (
  `id` tinyint unsigned NOT NULL DEFAULT '1',
  `legal_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trade_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tagline` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gstin` char(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pan` char(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gst_registration_type` enum('regular','composition','unregistered') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'regular',
