DROP TABLE IF EXISTS `expense_files`;
CREATE TABLE `expense_files` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `expense_id` bigint unsigned NOT NULL,
  `stored_file_id` bigint unsigned NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_ef_exp` (`expense_id`),
  KEY `fk_ef_file` (`stored_file_id`),
  CONSTRAINT `fk_ef_exp` FOREIGN KEY (`expense_id`) REFERENCES `expenses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ef_file` FOREIGN KEY (`stored_file_id`) REFERENCES `stored_files` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `expense_payments`;
CREATE TABLE `expense_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `expense_id` bigint unsigned NOT NULL,
  `payment_date` date NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `mode` enum('cash','upi','bank_transfer','neft','rtgs','imps','cheque','card','other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `bank_cash_account_id` int unsigned NOT NULL,
  `reference_no` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','void') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `reconciliation_status` enum('unmatched','partial','matched') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unmatched',
  `journal_entry_id` bigint unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ep_exp` (`expense_id`),
  KEY `fk_ep_bca` (`bank_cash_account_id`),
  KEY `fk_ep_je` (`journal_entry_id`),
  CONSTRAINT `fk_ep_bca` FOREIGN KEY (`bank_cash_account_id`) REFERENCES `bank_cash_accounts` (`id`),
  CONSTRAINT `fk_ep_exp` FOREIGN KEY (`expense_id`) REFERENCES `expenses` (`id`),
  CONSTRAINT `fk_ep_je` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`),
  CONSTRAINT `chk_ep_amount` CHECK ((`amount` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `expenses`;
CREATE TABLE `expenses` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `expense_number` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expense_date` date NOT NULL,
  `category_id` int unsigned NOT NULL,
  `vendor_contact_id` bigint unsigned DEFAULT NULL,
  `vendor_invoice_no` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vendor_invoice_date` date DEFAULT NULL,
  `vendor_gstin` char(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sac_hsn` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `project_contact_id` bigint unsigned DEFAULT NULL COMMENT 'client allocation',
  `taxable_amount` decimal(15,2) NOT NULL,
  `gst_type` enum('cgst_sgst','cgst_utgst','igst','none') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `gst_rate` decimal(6,3) NOT NULL DEFAULT '0.000',
  `cgst_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `sgst_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `utgst_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `igst_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `total_amount` decimal(15,2) NOT NULL,
  `itc_rule_id` int unsigned DEFAULT NULL,
  `itc_eligible_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `itc_ineligible_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `paid_through` enum('company','employee_reimbursable','unpaid') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unpaid',
  `paid_by_employee_id` bigint unsigned DEFAULT NULL,
  `reimbursement_status` enum('na','pending','reimbursed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'na',
  `payment_status` enum('unpaid','partial','paid') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unpaid',
  `paid_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `approval_status` enum('pending','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `approved_by` int unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `rejection_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recurring_expense_id` int unsigned DEFAULT NULL,
  `journal_entry_id` bigint unsigned DEFAULT NULL,
  `dedupe_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_exp_no` (`expense_number`),
  KEY `idx_exp_date` (`expense_date`),
  KEY `idx_exp_cat` (`category_id`),
  KEY `idx_exp_vendor` (`vendor_contact_id`),
  KEY `idx_exp_dedupe` (`dedupe_hash`),
  KEY `fk_exp_project` (`project_contact_id`),
  KEY `fk_exp_itc` (`itc_rule_id`),
  KEY `fk_exp_rec` (`recurring_expense_id`),
  KEY `fk_exp_je` (`journal_entry_id`),
  KEY `fk_exp_emp` (`paid_by_employee_id`),
  CONSTRAINT `fk_exp_cat` FOREIGN KEY (`category_id`) REFERENCES `expense_categories` (`id`),
  CONSTRAINT `fk_exp_emp` FOREIGN KEY (`paid_by_employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_exp_itc` FOREIGN KEY (`itc_rule_id`) REFERENCES `itc_rules` (`id`),
  CONSTRAINT `fk_exp_je` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`),
  CONSTRAINT `fk_exp_project` FOREIGN KEY (`project_contact_id`) REFERENCES `contacts` (`id`),
  CONSTRAINT `fk_exp_rec` FOREIGN KEY (`recurring_expense_id`) REFERENCES `recurring_expenses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_exp_vendor` FOREIGN KEY (`vendor_contact_id`) REFERENCES `contacts` (`id`),
  CONSTRAINT `chk_exp_amount` CHECK (((`taxable_amount` >= 0) and (`total_amount` >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `favorites`;
CREATE TABLE `favorites` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `label` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fav` (`user_id`,`url`),
  CONSTRAINT `fk_fav_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `financial_years`;
CREATE TABLE `financial_years` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(9) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'e.g. 2026-27',
  `short_code` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'e.g. 26-27',
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `is_current` tinyint(1) NOT NULL DEFAULT '0',
  `is_closed` tinyint(1) NOT NULL DEFAULT '0',
  `closed_by` int unsigned DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fy_code` (`code`),
  UNIQUE KEY `uq_fy_start` (`start_date`),
  CONSTRAINT `chk_fy_dates` CHECK ((`end_date` > `start_date`))
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
