DROP TABLE IF EXISTS `followups`;
CREATE TABLE `followups` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lead_id` bigint unsigned NOT NULL,
  `owner_id` int unsigned NOT NULL,
  `due_at` datetime NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `status` enum('pending','done','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `source_call_id` bigint unsigned DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `completed_by` int unsigned DEFAULT NULL,
  `outcome_notes` text COLLATE utf8mb4_unicode_ci,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_fu_owner` (`owner_id`,`status`,`due_at`),
  KEY `idx_fu_lead` (`lead_id`),
  KEY `fk_fu_call` (`source_call_id`),
  KEY `idx_fu_due` (`status`,`due_at`),
  CONSTRAINT `fk_fu_call` FOREIGN KEY (`source_call_id`) REFERENCES `call_logs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_fu_lead` FOREIGN KEY (`lead_id`) REFERENCES `leads` (`id`),
  CONSTRAINT `fk_fu_owner` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `google_sync_jobs`;
CREATE TABLE `google_sync_jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_id` bigint unsigned NOT NULL,
  `worksheet` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `action` enum('upsert','delete') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'upsert',
  `payload_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idempotency_key` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('pending','processing','done','failed','dead') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `attempts` smallint unsigned NOT NULL DEFAULT '0',
  `max_attempts` smallint unsigned NOT NULL DEFAULT '8',
  `next_attempt_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `locked_at` datetime DEFAULT NULL,
  `locked_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_error` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remote_row_ref` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_success_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gsj_idem` (`idempotency_key`),
  KEY `idx_gsj_due` (`status`,`next_attempt_at`),
  KEY `idx_gsj_entity` (`entity_type`,`entity_id`,`worksheet`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `google_sync_row_map`;
CREATE TABLE `google_sync_row_map` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `worksheet` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_id` bigint unsigned NOT NULL,
  `sheet_row` int unsigned NOT NULL,
  `last_synced_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_synced_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gsrm` (`worksheet`,`entity_type`,`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `google_sync_runs`;
CREATE TABLE `google_sync_runs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `started_at` datetime NOT NULL,
  `finished_at` datetime DEFAULT NULL,
  `trigger_source` enum('cron','manual','test') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cron',
  `processed` int unsigned NOT NULL DEFAULT '0',
  `succeeded` int unsigned NOT NULL DEFAULT '0',
  `failed` int unsigned NOT NULL DEFAULT '0',
  `message` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `google_sync_settings`;
CREATE TABLE `google_sync_settings` (
  `id` tinyint unsigned NOT NULL DEFAULT '1',
  `enabled` tinyint(1) NOT NULL DEFAULT '0',
  `spreadsheet_id` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `credentials_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'service-account JSON path outside webroot; never in DB',
  `worksheets` json NOT NULL COMMENT 'logical → tab name',
  `field_map` json NOT NULL COMMENT 'per worksheet column list',
  `frequency_minutes` smallint unsigned NOT NULL DEFAULT '5',
  `direction` enum('db_to_sheets') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'db_to_sheets' COMMENT 'two-way is future scope',
  `last_success_at` datetime DEFAULT NULL,
  `last_error` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_error_at` datetime DEFAULT NULL,
  `last_run_at` datetime DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  CONSTRAINT `chk_gss_singleton` CHECK ((`id` = 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `google_sync_settings` VALUES
