DROP TABLE IF EXISTS `holidays`;
CREATE TABLE `holidays` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `holiday_date` date NOT NULL,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_optional` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_hol` (`holiday_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `incentive_entries`;
CREATE TABLE `incentive_entries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `unique_ref` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'prevents duplicate incentive for the same source',
  `policy_id` int unsigned NOT NULL,
  `employee_id` bigint unsigned NOT NULL,
  `source_type` enum('lead_conversion','invoice','receipt_allocation','manual','clawback') COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_id` bigint unsigned DEFAULT NULL,
  `lead_id` bigint unsigned DEFAULT NULL,
  `contact_id` bigint unsigned DEFAULT NULL,
  `document_id` bigint unsigned DEFAULT NULL,
  `receipt_id` bigint unsigned DEFAULT NULL,
  `basis` enum('contract_value','invoiced_taxable','invoiced_gross','collections_net_of_tax','collections_gross','manual') COLLATE utf8mb4_unicode_ci NOT NULL,
  `basis_amount` decimal(15,2) NOT NULL,
  `share_percent` decimal(5,2) NOT NULL DEFAULT '100.00',
  `amount` decimal(12,2) NOT NULL,
  `period` char(7) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('proposed','approved','rejected','included','paid','clawed_back') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'proposed',
  `approved_by` int unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `rejection_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payroll_item_id` bigint unsigned DEFAULT NULL,
  `clawback_of_id` bigint unsigned DEFAULT NULL,
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ie_ref` (`unique_ref`),
  KEY `idx_ie_emp` (`employee_id`,`status`,`period`),
  KEY `fk_ie_policy` (`policy_id`),
  KEY `fk_ie_lead` (`lead_id`),
  KEY `fk_ie_doc` (`document_id`),
  KEY `fk_ie_receipt` (`receipt_id`),
  KEY `fk_ie_pi` (`payroll_item_id`),
  KEY `fk_ie_claw` (`clawback_of_id`),
  CONSTRAINT `fk_ie_claw` FOREIGN KEY (`clawback_of_id`) REFERENCES `incentive_entries` (`id`),
  CONSTRAINT `fk_ie_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`),
  CONSTRAINT `fk_ie_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_ie_lead` FOREIGN KEY (`lead_id`) REFERENCES `leads` (`id`),
  CONSTRAINT `fk_ie_pi` FOREIGN KEY (`payroll_item_id`) REFERENCES `payroll_items` (`id`),
  CONSTRAINT `fk_ie_policy` FOREIGN KEY (`policy_id`) REFERENCES `incentive_policies` (`id`),
  CONSTRAINT `fk_ie_receipt` FOREIGN KEY (`receipt_id`) REFERENCES `payment_receipts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `incentive_policies`;
CREATE TABLE `incentive_policies` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope_type` enum('all','role','user','service') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'role',
  `scope_ref` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'role code / user id / service id',
  `basis` enum('contract_value','invoiced_taxable','invoiced_gross','collections_net_of_tax','collections_gross') COLLATE utf8mb4_unicode_ci NOT NULL,
  `calc_type` enum('percent','fixed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'percent',
  `value` decimal(10,3) NOT NULL,
  `min_threshold` decimal(15,2) NOT NULL DEFAULT '0.00',
  `cutoff_day` tinyint unsigned NOT NULL DEFAULT '31' COMMENT 'entries after this day roll to next month',
  `requires_approval` tinyint(1) NOT NULL DEFAULT '1',
  `clawback_on_refund` tinyint(1) NOT NULL DEFAULT '1',
  `carry_forward` tinyint(1) NOT NULL DEFAULT '1',
  `effective_from` date NOT NULL,
  `effective_to` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `integration_settings`;
CREATE TABLE `integration_settings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `integration` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'smtp | google_sheets | ai',
  `setting_key` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `setting_value` text COLLATE utf8mb4_unicode_ci COMMENT 'secrets stored encrypted (CI Encryption)',
  `is_secret` tinyint(1) NOT NULL DEFAULT '0',
  `updated_by` int unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_is` (`integration`,`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `interview_scorecards`;
CREATE TABLE `interview_scorecards` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `interview_id` bigint unsigned NOT NULL,
  `criterion` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rating` tinyint unsigned NOT NULL,
  `comments` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `scored_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_isc` (`interview_id`,`criterion`),
  CONSTRAINT `fk_isc_int` FOREIGN KEY (`interview_id`) REFERENCES `interviews` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_isc_rating` CHECK ((`rating` between 1 and 5))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `interviews`;
CREATE TABLE `interviews` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `candidate_id` bigint unsigned NOT NULL,
  `round_no` smallint unsigned NOT NULL DEFAULT '1',
  `interview_type` enum('hr_screening','technical','managerial','group_discussion','assignment','final') COLLATE utf8mb4_unicode_ci NOT NULL,
  `scheduled_at` datetime NOT NULL,
  `duration_minutes` smallint unsigned NOT NULL DEFAULT '30',
  `mode` enum('in_person','phone','video') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_person',
  `location_or_link` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `interviewer_id` int unsigned NOT NULL,
  `status` enum('scheduled','completed','cancelled','no_show') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scheduled',
  `result` enum('pending','pass','fail','hold') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `overall_rating` tinyint unsigned DEFAULT NULL,
  `feedback` text COLLATE utf8mb4_unicode_ci,
  `attachment_file_id` bigint unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_int_cand` (`candidate_id`),
  KEY `idx_int_user` (`interviewer_id`,`scheduled_at`),
  KEY `fk_int_file` (`attachment_file_id`),
  CONSTRAINT `fk_int_cand` FOREIGN KEY (`candidate_id`) REFERENCES `candidates` (`id`),
  CONSTRAINT `fk_int_file` FOREIGN KEY (`attachment_file_id`) REFERENCES `stored_files` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_int_user` FOREIGN KEY (`interviewer_id`) REFERENCES `users` (`id`),
  CONSTRAINT `chk_int_rating` CHECK (((`overall_rating` is null) or (`overall_rating` between 1 and 5)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `itc_rules`;
CREATE TABLE `itc_rules` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `eligible` tinyint(1) NOT NULL DEFAULT '0',
  `eligible_percent` decimal(5,2) NOT NULL DEFAULT '0.00',
  `block_reference` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'e.g. Sec 17(5) clause, for accountant',
  `review_status` enum('suggested','accountant_reviewed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'suggested',
  `reviewed_by` int unsigned DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
