DROP TABLE IF EXISTS `job_description_versions`;
CREATE TABLE `job_description_versions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `job_opening_id` int unsigned NOT NULL,
  `version_no` smallint unsigned NOT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `responsibilities` text COLLATE utf8mb4_unicode_ci,
  `skills` json DEFAULT NULL,
  `must_have` json DEFAULT NULL,
  `nice_to_have` json DEFAULT NULL,
  `qualifications` text COLLATE utf8mb4_unicode_ci,
  `rubric` json NOT NULL COMMENT 'category weights summing to 100',
  `attachment_file_id` bigint unsigned DEFAULT NULL,
  `change_note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_jdv` (`job_opening_id`,`version_no`),
  KEY `fk_jdv_file` (`attachment_file_id`),
  CONSTRAINT `fk_jdv_file` FOREIGN KEY (`attachment_file_id`) REFERENCES `stored_files` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_jdv_job` FOREIGN KEY (`job_opening_id`) REFERENCES `job_openings` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `job_openings`;
CREATE TABLE `job_openings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `department_id` int unsigned DEFAULT NULL,
  `location` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `work_mode` enum('onsite','remote','hybrid') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'onsite',
  `experience_min` decimal(4,1) DEFAULT NULL,
  `experience_max` decimal(4,1) DEFAULT NULL,
  `salary_min` decimal(12,2) DEFAULT NULL,
  `salary_max` decimal(12,2) DEFAULT NULL,
  `openings_count` smallint unsigned NOT NULL DEFAULT '1',
  `recruiter_user_id` int unsigned DEFAULT NULL,
  `interviewer_user_id` int unsigned DEFAULT NULL,
  `status` enum('draft','open','on_hold','closed','filled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `current_jd_version_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_jo_code` (`code`),
  KEY `fk_jo_dept` (`department_id`),
  KEY `fk_jo_rec` (`recruiter_user_id`),
  KEY `fk_jo_int` (`interviewer_user_id`),
  KEY `fk_jo_jdv` (`current_jd_version_id`),
  CONSTRAINT `fk_jo_dept` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_jo_int` FOREIGN KEY (`interviewer_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_jo_jdv` FOREIGN KEY (`current_jd_version_id`) REFERENCES `job_description_versions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_jo_rec` FOREIGN KEY (`recruiter_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `journal_entries`;
CREATE TABLE `journal_entries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `entry_no` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entry_date` date NOT NULL,
  `period` char(7) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'YYYY-MM',
  `financial_year_id` int unsigned NOT NULL,
  `source_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_id` bigint unsigned DEFAULT NULL,
  `narration` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_debit` decimal(15,2) NOT NULL,
  `total_credit` decimal(15,2) NOT NULL,
  `reversal_of_id` bigint unsigned DEFAULT NULL,
  `reversed_by_id` bigint unsigned DEFAULT NULL,
  `posted_by` int unsigned DEFAULT NULL,
  `posted_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_je_no` (`entry_no`),
  KEY `idx_je_source` (`source_type`,`source_id`),
  KEY `idx_je_date` (`entry_date`),
  KEY `fk_je_fy` (`financial_year_id`),
  KEY `fk_je_rev` (`reversal_of_id`),
  CONSTRAINT `fk_je_fy` FOREIGN KEY (`financial_year_id`) REFERENCES `financial_years` (`id`),
  CONSTRAINT `fk_je_rev` FOREIGN KEY (`reversal_of_id`) REFERENCES `journal_entries` (`id`),
  CONSTRAINT `chk_je_balanced` CHECK ((`total_debit` = `total_credit`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `journal_lines`;
CREATE TABLE `journal_lines` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `journal_entry_id` bigint unsigned NOT NULL,
  `ledger_account_id` int unsigned NOT NULL,
  `contact_id` bigint unsigned DEFAULT NULL,
  `employee_id` bigint unsigned DEFAULT NULL,
  `bank_cash_account_id` int unsigned DEFAULT NULL,
  `debit` decimal(15,2) NOT NULL DEFAULT '0.00',
  `credit` decimal(15,2) NOT NULL DEFAULT '0.00',
  `memo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_jl_entry` (`journal_entry_id`),
  KEY `idx_jl_account` (`ledger_account_id`),
  KEY `idx_jl_contact` (`contact_id`),
  KEY `idx_jl_bca` (`bank_cash_account_id`),
  KEY `fk_jl_employee` (`employee_id`),
  CONSTRAINT `fk_jl_account` FOREIGN KEY (`ledger_account_id`) REFERENCES `ledger_accounts` (`id`),
  CONSTRAINT `fk_jl_bca` FOREIGN KEY (`bank_cash_account_id`) REFERENCES `bank_cash_accounts` (`id`),
  CONSTRAINT `fk_jl_contact` FOREIGN KEY (`contact_id`) REFERENCES `contacts` (`id`),
  CONSTRAINT `fk_jl_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_jl_entry` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`),
  CONSTRAINT `chk_jl_sides` CHECK (((`debit` >= 0) and (`credit` >= 0) and ((`debit` <= 0) or (`credit` <= 0)) and ((`debit` > 0) or (`credit` > 0))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `lead_activities`;
CREATE TABLE `lead_activities` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lead_id` bigint unsigned NOT NULL,
  `activity_type` enum('created','call','stage_change','assignment','followup_set','followup_done','visit','meeting','task','note','conversion','import','edit','dnd') COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `details` text COLLATE utf8mb4_unicode_ci,
  `ref_type` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ref_id` bigint unsigned DEFAULT NULL,
  `actor_id` int unsigned DEFAULT NULL,
  `occurred_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_la_lead` (`lead_id`,`occurred_at`),
  KEY `idx_la_actor` (`actor_id`,`occurred_at`),
  CONSTRAINT `fk_la_lead` FOREIGN KEY (`lead_id`) REFERENCES `leads` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `lead_assignments`;
CREATE TABLE `lead_assignments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lead_id` bigint unsigned NOT NULL,
  `from_user_id` int unsigned DEFAULT NULL,
  `to_user_id` int unsigned DEFAULT NULL,
  `assigned_by` int unsigned DEFAULT NULL,
  `reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assigned_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_las_lead` (`lead_id`),
  CONSTRAINT `fk_las_lead` FOREIGN KEY (`lead_id`) REFERENCES `leads` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `lead_conversion_links`;
CREATE TABLE `lead_conversion_links` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lead_id` bigint unsigned NOT NULL,
  `contact_id` bigint unsigned NOT NULL,
  `document_id` bigint unsigned DEFAULT NULL,
  `attributed_user_id` int unsigned DEFAULT NULL,
  `attribution` json DEFAULT NULL COMMENT 'split credit: [{user_id, percent}]',
  `contract_value` decimal(15,2) DEFAULT NULL,
  `converted_by` int unsigned DEFAULT NULL,
  `converted_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lcl_lead` (`lead_id`),
  KEY `fk_lcl_contact` (`contact_id`),
  KEY `fk_lcl_doc` (`document_id`),
  KEY `idx_lcl_conv` (`converted_at`),
  CONSTRAINT `fk_lcl_contact` FOREIGN KEY (`contact_id`) REFERENCES `contacts` (`id`),
  CONSTRAINT `fk_lcl_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_lcl_lead` FOREIGN KEY (`lead_id`) REFERENCES `leads` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

