  `contact_id` bigint unsigned DEFAULT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `meeting_at` datetime NOT NULL,
  `duration_minutes` smallint unsigned NOT NULL DEFAULT '30',
  `mode` enum('in_person','phone','video') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_person',
  `location_or_link` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `organizer_id` int unsigned NOT NULL,
  `attendee_ids` json DEFAULT NULL,
  `status` enum('scheduled','completed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scheduled',
