DROP TABLE IF EXISTS `money_transfers`;
CREATE TABLE `money_transfers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `transfer_number` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `transfer_date` date NOT NULL,
  `from_account_id` int unsigned NOT NULL,
  `to_account_id` int unsigned NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `transfer_kind` enum('cash_deposit','cash_withdrawal','bank_transfer','upi_settlement','owner_clearing_settlement','other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_no` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','void') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `reconciliation_status` enum('unmatched','partial','matched') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unmatched',
  `journal_entry_id` bigint unsigned DEFAULT NULL,
  `void_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `voided_by` int unsigned DEFAULT NULL,
  `voided_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mt_no` (`transfer_number`),
  KEY `idx_mt_date` (`transfer_date`),
  KEY `fk_mt_from` (`from_account_id`),
  KEY `fk_mt_to` (`to_account_id`),
  KEY `fk_mt_je` (`journal_entry_id`),
  CONSTRAINT `fk_mt_from` FOREIGN KEY (`from_account_id`) REFERENCES `bank_cash_accounts` (`id`),
  CONSTRAINT `fk_mt_je` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`),
  CONSTRAINT `fk_mt_to` FOREIGN KEY (`to_account_id`) REFERENCES `bank_cash_accounts` (`id`),
  CONSTRAINT `chk_mt_accounts` CHECK ((`from_account_id` <> `to_account_id`)),
  CONSTRAINT `chk_mt_amount` CHECK ((`amount` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `link` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `entity_type` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `entity_id` bigint unsigned DEFAULT NULL,
  `dedupe_key` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `read_at` datetime DEFAULT NULL,
  `emailed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_notif_dedupe` (`user_id`,`dedupe_key`),
  KEY `idx_notif_user` (`user_id`,`read_at`,`created_at`),
  CONSTRAINT `fk_notif_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payment_allocations`;
CREATE TABLE `payment_allocations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `receipt_id` bigint unsigned NOT NULL,
  `document_id` bigint unsigned NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `allocated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `allocated_by` int unsigned DEFAULT NULL,
  `journal_entry_id` bigint unsigned DEFAULT NULL COMMENT 'set when applied from advances after the receipt',
  `reversed_at` datetime DEFAULT NULL,
  `reversed_by` int unsigned DEFAULT NULL,
  `reversal_journal_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pa_doc` (`document_id`),
  KEY `idx_pa_receipt` (`receipt_id`),
  CONSTRAINT `fk_pa_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`),
  CONSTRAINT `fk_pa_receipt` FOREIGN KEY (`receipt_id`) REFERENCES `payment_receipts` (`id`),
  CONSTRAINT `chk_pa_amount` CHECK ((`amount` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payment_receipts`;
CREATE TABLE `payment_receipts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `receipt_type` enum('receipt','refund') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'receipt',
  `receipt_number` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sequence_id` int unsigned DEFAULT NULL,
  `sequence_number` int unsigned DEFAULT NULL,
  `financial_year_id` int unsigned NOT NULL,
  `contact_id` bigint unsigned NOT NULL,
  `receipt_date` date NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `mode` enum('cash','upi','bank_transfer','neft','rtgs','imps','cheque','card','other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `bank_cash_account_id` int unsigned NOT NULL,
  `reference_no` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'UTR / cheque no / txn id',
  `cheque_date` date DEFAULT NULL,
  `cheque_status` enum('na','pending','cleared','bounced') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'na',
  `allocated_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `unapplied_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `refund_of_receipt_id` bigint unsigned DEFAULT NULL,
  `status` enum('active','void') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `requires_review` tinyint(1) NOT NULL DEFAULT '0',
  `reconciliation_status` enum('unmatched','partial','matched') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unmatched',
  `reconciled_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `dedupe_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `journal_entry_id` bigint unsigned DEFAULT NULL,
  `void_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `voided_by` int unsigned DEFAULT NULL,
  `voided_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pr_number` (`financial_year_id`,`receipt_number`),
  UNIQUE KEY `uq_pr_seq` (`sequence_id`,`sequence_number`),
  KEY `idx_pr_contact` (`contact_id`),
  KEY `idx_pr_date` (`receipt_date`),
  KEY `idx_pr_dedupe` (`dedupe_hash`),
  KEY `fk_pr_bca` (`bank_cash_account_id`),
  KEY `fk_pr_je` (`journal_entry_id`),
  KEY `fk_pr_refund` (`refund_of_receipt_id`),
  CONSTRAINT `fk_pr_bca` FOREIGN KEY (`bank_cash_account_id`) REFERENCES `bank_cash_accounts` (`id`),
  CONSTRAINT `fk_pr_contact` FOREIGN KEY (`contact_id`) REFERENCES `contacts` (`id`),
  CONSTRAINT `fk_pr_fy` FOREIGN KEY (`financial_year_id`) REFERENCES `financial_years` (`id`),
  CONSTRAINT `fk_pr_je` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`),
  CONSTRAINT `fk_pr_refund` FOREIGN KEY (`refund_of_receipt_id`) REFERENCES `payment_receipts` (`id`),
  CONSTRAINT `fk_pr_seq` FOREIGN KEY (`sequence_id`) REFERENCES `document_sequences` (`id`),
  CONSTRAINT `chk_pr_alloc` CHECK (((`allocated_amount` >= 0) and (`unapplied_amount` >= 0))),
  CONSTRAINT `chk_pr_amount` CHECK ((`amount` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payroll_adjustments`;
CREATE TABLE `payroll_adjustments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `payroll_run_id` int unsigned NOT NULL,
  `payroll_item_id` bigint unsigned NOT NULL,
  `adjustment_type` enum('earning','deduction') COLLATE utf8mb4_unicode_ci NOT NULL,
  `label` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `reason` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `journal_entry_id` bigint unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_padj_run` (`payroll_run_id`),
  KEY `fk_padj_item` (`payroll_item_id`),
  KEY `fk_padj_je` (`journal_entry_id`),
  CONSTRAINT `fk_padj_item` FOREIGN KEY (`payroll_item_id`) REFERENCES `payroll_items` (`id`),
  CONSTRAINT `fk_padj_je` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`),
  CONSTRAINT `fk_padj_run` FOREIGN KEY (`payroll_run_id`) REFERENCES `payroll_runs` (`id`),
  CONSTRAINT `chk_padj` CHECK ((`amount` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payroll_item_components`;
CREATE TABLE `payroll_item_components` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `payroll_item_id` bigint unsigned NOT NULL,
  `component_type` enum('earning','deduction','employer','info') COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `label` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `ref_type` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ref_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pic_item` (`payroll_item_id`),
  CONSTRAINT `fk_pic_item` FOREIGN KEY (`payroll_item_id`) REFERENCES `payroll_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payroll_items`;
CREATE TABLE `payroll_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `payroll_run_id` int unsigned NOT NULL,
  `employee_id` bigint unsigned NOT NULL,
  `salary_structure_id` bigint unsigned DEFAULT NULL,
  `days_in_period` decimal(5,1) NOT NULL,
  `proration_days` decimal(5,1) NOT NULL,
  `payable_days` decimal(5,1) NOT NULL,
  `present_days` decimal(5,1) NOT NULL DEFAULT '0.0',
  `paid_leave_days` decimal(5,1) NOT NULL DEFAULT '0.0',
  `unpaid_leave_days` decimal(5,1) NOT NULL DEFAULT '0.0',
  `absent_days` decimal(5,1) NOT NULL DEFAULT '0.0',
  `holiday_days` decimal(5,1) NOT NULL DEFAULT '0.0',
  `week_off_days` decimal(5,1) NOT NULL DEFAULT '0.0',
  `unmarked_days` decimal(5,1) NOT NULL DEFAULT '0.0',
  `base_monthly` decimal(12,2) NOT NULL,
  `fixed_earned` decimal(12,2) NOT NULL DEFAULT '0.00',
  `allowances` decimal(12,2) NOT NULL DEFAULT '0.00',
  `overtime_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `incentive_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `reimbursement_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `gross_pay` decimal(12,2) NOT NULL DEFAULT '0.00',
  `statutory_deductions` decimal(12,2) NOT NULL DEFAULT '0.00',
  `recovery_deductions` decimal(12,2) NOT NULL DEFAULT '0.00',
  `other_deductions` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total_deductions` decimal(12,2) NOT NULL DEFAULT '0.00',
  `net_pay` decimal(12,2) NOT NULL DEFAULT '0.00',
  `amount_paid` decimal(12,2) NOT NULL DEFAULT '0.00',
  `balance` decimal(12,2) NOT NULL DEFAULT '0.00',
  `payment_status` enum('unpaid','partial','paid') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unpaid',
  `last_payment_date` date DEFAULT NULL,
  `adjustment_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pi` (`payroll_run_id`,`employee_id`),
  KEY `fk_pi_emp` (`employee_id`),
  KEY `fk_pi_ss` (`salary_structure_id`),
  CONSTRAINT `fk_pi_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_pi_run` FOREIGN KEY (`payroll_run_id`) REFERENCES `payroll_runs` (`id`),
  CONSTRAINT `fk_pi_ss` FOREIGN KEY (`salary_structure_id`) REFERENCES `salary_structures` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payroll_payments`;
CREATE TABLE `payroll_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `payroll_run_id` int unsigned NOT NULL,
  `payroll_item_id` bigint unsigned NOT NULL,
  `payment_date` date NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `mode` enum('cash','upi','bank_transfer','neft','rtgs','imps','cheque','other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `bank_cash_account_id` int unsigned NOT NULL,
  `reference_no` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reconciliation_status` enum('unmatched','partial','matched') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unmatched',
  `journal_entry_id` bigint unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_pp_item` (`payroll_item_id`),
  KEY `fk_pp_run` (`payroll_run_id`),
  KEY `fk_pp_bca` (`bank_cash_account_id`),
  KEY `fk_pp_je` (`journal_entry_id`),
  CONSTRAINT `fk_pp_bca` FOREIGN KEY (`bank_cash_account_id`) REFERENCES `bank_cash_accounts` (`id`),
  CONSTRAINT `fk_pp_item` FOREIGN KEY (`payroll_item_id`) REFERENCES `payroll_items` (`id`),
  CONSTRAINT `fk_pp_je` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`),
  CONSTRAINT `fk_pp_run` FOREIGN KEY (`payroll_run_id`) REFERENCES `payroll_runs` (`id`),
  CONSTRAINT `chk_pp` CHECK ((`amount` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payroll_runs`;
CREATE TABLE `payroll_runs` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `period` char(7) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'YYYY-MM',
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `status` enum('draft','calculated','finalized','partially_paid','paid') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `is_locked` tinyint(1) NOT NULL DEFAULT '0',
  `total_gross` decimal(15,2) NOT NULL DEFAULT '0.00',
  `total_deductions` decimal(15,2) NOT NULL DEFAULT '0.00',
  `total_net` decimal(15,2) NOT NULL DEFAULT '0.00',
  `total_paid` decimal(15,2) NOT NULL DEFAULT '0.00',
  `calculated_by` int unsigned DEFAULT NULL,
  `calculated_at` datetime DEFAULT NULL,
  `finalized_by` int unsigned DEFAULT NULL,
  `finalized_at` datetime DEFAULT NULL,
  `journal_entry_id` bigint unsigned DEFAULT NULL,
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pr_period` (`period`),
  KEY `fk_prun_je` (`journal_entry_id`),
  CONSTRAINT `fk_prun_je` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payslips`;
CREATE TABLE `payslips` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `payroll_item_id` bigint unsigned NOT NULL,
  `version` smallint unsigned NOT NULL DEFAULT '1',
  `stored_file_id` bigint unsigned NOT NULL,
  `generated_by` int unsigned DEFAULT NULL,
  `generated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ps` (`payroll_item_id`,`version`),
  KEY `fk_ps_file` (`stored_file_id`),
  CONSTRAINT `fk_ps_file` FOREIGN KEY (`stored_file_id`) REFERENCES `stored_files` (`id`),
  CONSTRAINT `fk_ps_item` FOREIGN KEY (`payroll_item_id`) REFERENCES `payroll_items` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `perm_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `module` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_dangerous` tinyint(1) NOT NULL DEFAULT '0',
  `scope` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_perm_key` (`perm_key`),
  KEY `idx_perm_module` (`module`)
) ENGINE=InnoDB AUTO_INCREMENT=175 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
