DROP TABLE IF EXISTS `reconciliation_matches`;
CREATE TABLE `reconciliation_matches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `bank_import_line_id` bigint unsigned NOT NULL,
  `match_type` enum('receipt','transfer_in','transfer_out','expense_payment','salary_payment','refund','journal') COLLATE utf8mb4_unicode_ci NOT NULL,
  `match_id` bigint unsigned NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `confidence` decimal(5,2) NOT NULL DEFAULT '0.00',
  `status` enum('suggested','confirmed','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'suggested',
  `confirmed_by` int unsigned DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rm` (`bank_import_line_id`,`match_type`,`match_id`),
  KEY `idx_rm_target` (`match_type`,`match_id`,`status`),
  CONSTRAINT `fk_rm_line` FOREIGN KEY (`bank_import_line_id`) REFERENCES `bank_import_lines` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `recruitment_events`;
CREATE TABLE `recruitment_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `candidate_id` bigint unsigned NOT NULL,
  `event_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `to_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `actor_id` int unsigned DEFAULT NULL,
  `source` enum('manual','system','ai_proposed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `proposal_status` enum('na','proposed','accepted','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'na',
  `ai_evaluation_id` bigint unsigned DEFAULT NULL,
  `ref_type` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ref_id` bigint unsigned DEFAULT NULL,
  `occurred_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_re_cand` (`candidate_id`,`occurred_at`),
  KEY `fk_re_ace` (`ai_evaluation_id`),
  CONSTRAINT `fk_re_ace` FOREIGN KEY (`ai_evaluation_id`) REFERENCES `ai_cv_evaluations` (`id`),
  CONSTRAINT `fk_re_cand` FOREIGN KEY (`candidate_id`) REFERENCES `candidates` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `recurring_billing_lines`;
CREATE TABLE `recurring_billing_lines` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `profile_id` int unsigned NOT NULL,
  `line_no` smallint unsigned NOT NULL,
  `service_id` int unsigned DEFAULT NULL,
  `item_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `sac_code` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qty` decimal(14,3) NOT NULL DEFAULT '1.000',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit_rate` decimal(15,4) NOT NULL,
  `tax_treatment` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'regular',
  `gst_rate` decimal(6,3) NOT NULL DEFAULT '0.000',
  PRIMARY KEY (`id`),
  KEY `fk_rbl_profile` (`profile_id`),
  KEY `fk_rbl_svc` (`service_id`),
  CONSTRAINT `fk_rbl_profile` FOREIGN KEY (`profile_id`) REFERENCES `recurring_billing_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rbl_svc` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `recurring_billing_profiles`;
CREATE TABLE `recurring_billing_profiles` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contact_id` bigint unsigned NOT NULL,
  `doc_type` enum('tax_invoice','cash_memo','proforma') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tax_invoice',
  `frequency` enum('monthly','quarterly','half_yearly','yearly') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'monthly',
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `next_run_date` date NOT NULL,
  `contract_value` decimal(15,2) DEFAULT NULL,
  `installments_total` smallint unsigned DEFAULT NULL,
  `installments_done` smallint unsigned NOT NULL DEFAULT '0',
  `place_of_supply_state_code` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gst_type` enum('cgst_sgst','cgst_utgst','igst','none') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `renewal_reminder_days` smallint unsigned NOT NULL DEFAULT '15',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `last_generated_document_id` bigint unsigned DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_rbp_next` (`is_active`,`next_run_date`),
  KEY `fk_rbp_contact` (`contact_id`),
  CONSTRAINT `fk_rbp_contact` FOREIGN KEY (`contact_id`) REFERENCES `contacts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `recurring_expenses`;
CREATE TABLE `recurring_expenses` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_id` int unsigned NOT NULL,
  `vendor_contact_id` bigint unsigned DEFAULT NULL,
  `amount` decimal(15,2) NOT NULL,
  `frequency` enum('monthly','quarterly','half_yearly','yearly') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'monthly',
  `next_due_date` date NOT NULL,
  `reminder_days_before` smallint unsigned NOT NULL DEFAULT '5',
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_rexp_cat` (`category_id`),
  KEY `fk_rexp_vendor` (`vendor_contact_id`),
  CONSTRAINT `fk_rexp_cat` FOREIGN KEY (`category_id`) REFERENCES `expense_categories` (`id`),
  CONSTRAINT `fk_rexp_vendor` FOREIGN KEY (`vendor_contact_id`) REFERENCES `contacts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `report_exports`;
CREATE TABLE `report_exports` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `report_code` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `format` enum('xlsx','csv','pdf') COLLATE utf8mb4_unicode_ci NOT NULL,
  `filters` json DEFAULT NULL,
  `stored_file_id` bigint unsigned DEFAULT NULL,
  `row_count` int unsigned DEFAULT NULL,
  `status` enum('generated','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'generated',
  `downloaded_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_re_user` (`user_id`,`created_at`),
  KEY `fk_re_file` (`stored_file_id`),
  CONSTRAINT `fk_re_file` FOREIGN KEY (`stored_file_id`) REFERENCES `stored_files` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_re_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `role_permissions`;
CREATE TABLE `role_permissions` (
  `role_id` int unsigned NOT NULL,
  `permission_id` int unsigned NOT NULL,
  `granted_by` int unsigned DEFAULT NULL,
  `granted_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`role_id`,`permission_id`),
  KEY `idx_rp_perm` (`permission_id`),
  CONSTRAINT `fk_rp_perm` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rp_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
