DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `landing_url` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'page opened after sign-in ("" = owner dashboard)',
  `is_super` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'implicitly holds every permission',
  `is_system` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'starter role (still editable, not deletable if super)',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_roles_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `roles` VALUES
('1','super_admin','Owner / Super Admin','All modules, approvals and permission management. Privileged actions are logged.','','1','1','1',NULL,NULL,'2026-10-28 18:05:11',NULL),
('2','accountant','Accountant','Billing, finance, bank, GST reports. No CRM lead lists or candidate CVs by default.','','0','1','1',NULL,NULL,'2026-10-28 18:05:11',NULL),
('3','billing_operator','Billing Operator','Creates invoice/cash memo drafts for allowed customers. No revenue totals, bank, GST dashboards, CRM, HR. Finalize/print individually assignable.','dashboard/billing','0','1','1',NULL,NULL,'2026-10-28 18:05:11',NULL),
('4','crm_manager','CRM Manager','All CRM data, assignments, team performance and Sheets sync status. No bank details or salaries.','','0','1','1',NULL,NULL,'2026-10-28 18:05:11',NULL),
('5','telecaller','Telecaller','Own assigned leads, calls, follow-ups, meetings, visits, tasks and own stats only.','crm/today','0','1','1',NULL,NULL,'2026-10-28 18:05:11',NULL),
('6','sales_executive','Sales Executive','Assigned leads, visits, meetings and quotations.','crm/today','0','1','1',NULL,NULL,'2026-10-28 18:05:11',NULL),
('7','hr_manager','HR Manager','Recruitment, employees, attendance, leave, incentives and payroll.','dashboard/hr','0','1','1',NULL,NULL,'2026-10-28 18:05:11',NULL),
('8','hr_recruiter','HR Recruiter','JDs, assigned applicants, interviews, candidate timeline and scoped AI CV review. No finance, CRM or salary.','dashboard/hr','0','1','1',NULL,NULL,'2026-10-28 18:05:12',NULL),
('9','payroll_manager','Payroll Manager','Attendance, approved incentives, payroll calculation and payslips. No billing/CRM.','dashboard/hr','0','1','1',NULL,NULL,'2026-10-28 18:05:12',NULL),
('10','employee','Employee','Own attendance, leaves, payslips and assigned tasks only.','me','0','1','1',NULL,NULL,'2026-10-28 18:05:12',NULL),
('11','auditor','Auditor (Read Only)','Time-limited read-only access to selected registers and audit trails. Assign with an expiry date.','','0','1','1',NULL,NULL,'2026-10-28 18:05:12',NULL);

DROP TABLE IF EXISTS `salary_structure_components`;
CREATE TABLE `salary_structure_components` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `salary_structure_id` bigint unsigned NOT NULL,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `label` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `component_type` enum('earning','deduction') COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `is_prorated` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ssc` (`salary_structure_id`,`code`),
  CONSTRAINT `fk_ssc_ss` FOREIGN KEY (`salary_structure_id`) REFERENCES `salary_structures` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `salary_structures`;
CREATE TABLE `salary_structures` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL,
  `effective_from` date NOT NULL,
  `salary_type` enum('monthly','daily') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'monthly',
  `ctc_annual` decimal(12,2) DEFAULT NULL,
  `monthly_gross` decimal(12,2) NOT NULL COMMENT 'fixed monthly pay (or daily rate when salary_type=daily)',
  `proration_basis` enum('calendar_days','fixed_30','working_days') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'calendar_days',
  `overtime_rate_per_hour` decimal(10,2) DEFAULT NULL,
  `pf_applicable` tinyint(1) NOT NULL DEFAULT '0',
  `esi_applicable` tinyint(1) NOT NULL DEFAULT '0',
  `pt_applicable` tinyint(1) NOT NULL DEFAULT '0',
  `tds_monthly` decimal(10,2) NOT NULL DEFAULT '0.00',
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ss` (`employee_id`,`effective_from`),
  CONSTRAINT `fk_ss_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `chk_ss_gross` CHECK ((`monthly_gross` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `saved_views`;
CREATE TABLE `saved_views` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `module` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `filters` json DEFAULT NULL,
  `columns` json DEFAULT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sv` (`user_id`,`module`),
  CONSTRAINT `fk_sv_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `services`;
CREATE TABLE `services` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `sac_code` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Service',
  `default_rate` decimal(15,2) NOT NULL DEFAULT '0.00',
  `default_tax_rate_id` int unsigned DEFAULT NULL,
  `default_tax_treatment` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'regular',
  `pos_rule` enum('default','review_required') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'default' COMMENT 'special place-of-supply rules need human review',
  `is_recurring_type` tinyint(1) NOT NULL DEFAULT '0',
  `review_status` enum('suggested','accountant_reviewed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'suggested',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_svc_code` (`code`),
  KEY `fk_svc_tax` (`default_tax_rate_id`),
  KEY `fk_svc_treat` (`default_tax_treatment`),
  CONSTRAINT `fk_svc_tax` FOREIGN KEY (`default_tax_rate_id`) REFERENCES `tax_rates` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_svc_treat` FOREIGN KEY (`default_tax_treatment`) REFERENCES `tax_treatments` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
